class Configuration(CommonPage):
    """
    The class corresponding to Configuration page on selenium_coam web, all operations under Configuration
    page will be implemented or added in its corresponding classes.
    """
    _instance_dict = {}

    def __init__(self):
        if not self._instance_dict:
            self._instance_dict = {"Commissioning Wizard": CommissioningWizardPage(),
                                   "Parameter Editor": ParameterEditorPage(),
                                   "Definition Errors": DefinitionErrorsPage(),
                                   "Relation Errors": RelationErrorsPage(),
                                   "Hardware Errors": HardwareErrorsPage(),
                                   "Compare Objects": CompareObjectsPage(),
                                   "BTS Certificates": BtsCertificatesPage(),
                                   "Automatic Management": AutomaticManagementPage(),
                                   "Certificate Revocation Lists": CertificateRevocationListsPage(),
                                   "Vendor Certificates": VendorCertificatesPage(),
                                   "Configuration Reset": ConfigurationResetPage(),
                                   "Centralized RAE Management": CentralizedRaeManagementPage()}
        super(Configuration, self).__init__(self._instance_dict)


class ConfigurationCommonAction(NavigationPanel, ViewPanel, DetailPanel):
    _LOAD_COMMISSIONING_FILE_BUTTON_SCRIPT = "load-action-button input"
    _CREATE_CONFIGURATION_BUTTON_XPATH = '//create-configuration-button//button'
    _LOAD_COMMISSIONING_FILE_BUTTON_XPATH = '//load-action-button//input'
    _UNDO_CHANGES_BUTTON_XPATH = '//undo-changes-action-button//button'
    _VALIDATE_PLAN_BUTTON_XPATH = '//revalidate-action-button//button'
    _ACTIVATE_PLAN_BUTTON_XPATH = '//deploy-action-button//button'
    _SAVE_REPORT_BUTTON_XPATH = '//commissioning-report//button'
    _SAVE_BTS_CONFIGURATION_ICON_XPATH = '//save-bts-configuration-button//button'
    _OBJECT_NAME_FILTER_XPATH = '//ui-text-input[@a-type="filter" and @a-placeholder="Object name"]//input'
    _OBJECT_NAME_XPATH = '(//span[@title="{}" or @aria-label="{}"])'
    _ADD_OBJECT_BUTTON_XPATH = _OBJECT_NAME_XPATH + '//following-sibling::div//*[@a-icon="plus"]/button'
    _REMOVE_OBJECT_BUTTON_XPATH = _OBJECT_NAME_XPATH + '//following-sibling::div//*[@a-icon="trash"]/button'
    _CHECK_OBJECT_NAME_XPATH = '//b[text()="{}"]/following-sibling::small'
    _instance = None

    def __new__(cls, *args, **kw):
        if not cls._instance:
            cls._instance = super(ConfigurationCommonAction, cls).__new__(cls)
        return cls._instance

    def _get_valid_object_xpath(self, object_name, last_level_object_name, timeout=60):
        object_xpath_list = self._get_object_xpath_list(last_level_object_name, timeout)
        valid_object_xpath = object_xpath_list[0]
        check_object_name_xpath = self._CHECK_OBJECT_NAME_XPATH.format(last_level_object_name)
        for object_xpath in object_xpath_list:
            self.click_enabled_element((By.XPATH, object_xpath))
            self.wait_for_visibility((By.XPATH, check_object_name_xpath), timeout)
            check_object_name = self.get_text_by_xpath(check_object_name_xpath)
            if object_name == check_object_name:
                valid_object_xpath = object_xpath
        return valid_object_xpath

    def _get_object_xpath_list(self, object_name, timeout):
        object_xpath_list = []
        filter_object_xpath = self._OBJECT_NAME_XPATH.format(object_name, object_name)
        self.wait_for_visibility((By.XPATH, filter_object_xpath), timeout)
        filter_object_elements = self.driver.find_elements_by_xpath(filter_object_xpath)
        for idx in range(len(filter_object_elements)):
            object_xpath_list.append(filter_object_xpath + "[{}]".format(idx + 1))
        return object_xpath_list

    def _input_and_choose_object(self, object_name, timeout=60):
        """
        Choose object after inputting object name
        :param object_name: str, where object will be added in
        :param timeout: int, timeout
        """
        last_level_object_name = object_name.split('/')[-1]
        self.insert_text_to_enable_element_and_enter((By.XPATH, self._OBJECT_NAME_FILTER_XPATH),
                                                     last_level_object_name, timeout)
        valid_object_xpath = self._get_valid_object_xpath(object_name, last_level_object_name, timeout)
        self.click_enabled_element((By.XPATH, valid_object_xpath))
        return last_level_object_name

    def add_object(self, object_name, object_class_name, plan_to_copy_from, copy_from, include_subobject, id_value,
                   is_load_default_values, timeout):
        """
        Adding object under navigation panel
        :param object_name: str, where object will be added in
        :param object_class_name: str, name of object class
        :param plan_to_copy_from: str, where plan to copy object from
        :param copy_from: str, where copy object from
        :param include_subobject: boolean
        :param id_value: str, default is None
        :param is_load_default_values: boolean
        :param timeout: int, timeout
        """
        object_name = self._input_and_choose_object(object_name)
        self.click_enabled_element((By.XPATH, self._ADD_OBJECT_BUTTON_XPATH.format(object_name, object_name)),
                                   timeout)

        add_object_modal = AddObjectModal()
        add_object_modal.wait_until_add_object_modal_appear(timeout)
        add_object_modal.add_object(object_class_name,
                                    plan_to_copy_from,
                                    copy_from,
                                    include_subobject,
                                    id_value,
                                    is_load_default_values,
                                    timeout)
        add_object_modal.submit(timeout)

    def remove_object(self, object_name, timeout=60):
        """
        Remove object under navigation panel
        :param object_name: str, object will be removed
        :param timeout: int, timeout
        """
        object_name = self._input_and_choose_object(object_name, timeout)
        self.click_enabled_element((By.XPATH, self._REMOVE_OBJECT_BUTTON_XPATH.format(object_name, object_name)),
                                   timeout)

        remove_object_modal = RemoveObjectModal()
        remove_object_modal.wait_until_remove_object_modal_appear(timeout)
        remove_object_modal.submit(timeout)

    def create_plan(self, is_copy, copy_configuration_from, configuration_name, timeout):
        self.click_enabled_element((By.XPATH, self._CREATE_CONFIGURATION_BUTTON_XPATH), timeout)
        configuration_modal = CreateNewConfigurationModal()
        configuration_modal.wait_for_creat_new_configuration_modal_appear(timeout)
        configuration_modal.create_new_configuration(is_copy, copy_configuration_from, configuration_name, timeout)

    def load_commissioning_file_and_check_load_status(self, file_path, timeout=60):
        """
        Load commissioning file and check load status
        :param file_path: str, scf file path
        :param timeout: int, timeout
        :return: boolean, True or False
        """
        self.load_file_from_hidden_button(self._LOAD_COMMISSIONING_FILE_BUTTON_SCRIPT,
                                          self._LOAD_COMMISSIONING_FILE_BUTTON_XPATH, file_path, timeout)
        load_scf_file_modal = LoadScfFileModal()
        load_scf_file_modal.wait_until_load_file_modal_appear(timeout)
        load_status = load_scf_file_modal.check_status_after_loading_scf_file(timeout)
        load_scf_file_modal.confirm()
        return load_status

    def undo_changes(self, timeout=60):
        """
        Undo changes
        :param timeout: int, timeout
        """
        self.click_enabled_element((By.XPATH, self._UNDO_CHANGES_BUTTON_XPATH), timeout)

        undo_changes_modal = UndoChangesModal()
        undo_changes_modal.wait_until_undo_changes_modal_appear(timeout)
        undo_changes_modal.execute_undo_changes(timeout)

    def validate_plan(self, timeout=60):
        """
        Validate definition errors plan
        :return: str, validation result
        """
        self.click_enabled_element((By.XPATH, self._VALIDATE_PLAN_BUTTON_XPATH), timeout)

    def activate_plan(self, download_plan_without_activation=False,
                      activate_plan_despite_errors=False, execute=True, timeout=60):
        """
        Activate plan after loading scf file
        :param download_plan_without_activation: boolean, if False, download plan without activation will not be
        selected, default False
        :param activate_plan_despite_errors: boolean, if True, activate or download plan despite of validation errors
        will be selected, default False
        :param execute: boolean, if True, click execute button, otherwise close the activate plan modal
        :param timeout: int, timeout
        :return: boolean, if True, activate successfully, otherwise, activate failed
        """
        activate_status = False
        try:
            self.click_enabled_element((By.XPATH, self._ACTIVATE_PLAN_BUTTON_XPATH), timeout=20)
        except TimeoutException:
            return activate_status

        activate_plan_modal = ActivatePlanModal()
        activate_plan_modal.wait_until_actiavte_plan_modal_appear(timeout)

        activate_plan_modal.select_download_plan_without_activation(download_plan_without_activation)
        activate_plan_modal.select_activate_or_download_plan_despite_errors(activate_plan_despite_errors)

        if execute:
            activate_status = activate_plan_modal.execute()
        activate_plan_modal.close(timeout)
        return activate_status

    def save_report(self, timeout=60):
        """
        Save report
        :param timeout: int, timeout
        :return: str, report path
        """
        self.click_enabled_element((By.XPATH, self._SAVE_REPORT_BUTTON_XPATH))

        save_report_modal = SaveReportModal()
        save_report_modal.wait_until_save_report_modal_appear(timeout)
        report_file_path = save_report_modal.save_report(timeout)
        save_report_modal.close(timeout)
        return report_file_path

    def save_bts_configuration(self, save_configuration_type_str, save_planned_parameter_changes):
        """
        Keyword for save bts configuration
        :param save_configuration_type_str: str, type of save type
                0: Save as SCF - BTS configuration only
                1: Save as full BTS runtime configuration
                2: Save BTS runtime information only
        :param save_planned_parameter_changes: bool, save the planned parameter changes or not
        :return str, path to download configuration file
        """
        self.click_enabled_element_after_visible((By.XPATH, self._SAVE_BTS_CONFIGURATION_ICON_XPATH))
        save_configuration_modal = SaveBtsConfigurationModal()
        save_configuration_modal.wait_until_save_bts_configuration_modal_appear()
        return save_configuration_modal.save(save_configuration_type_str, save_planned_parameter_changes)


