class DefinitionErrorsPageViewPanel(ViewPanel):
    _VALIDATE_PLAN_RESULT_XPATH = '//definition-errors/div'
    _DEFINITION_ERRORS_TABLE_XPATH = '//definition-errors//table'
    _DEFINITION_ERRORS_TABLE_HEAD_XPATH = '//definition-errors//thead//' \
                                          'th[not(contains(@class,"parameter-action-buttons-cell"))]//div'
    _ALL_ERROR_INFO_XPATH = '//definition-errors//tbody//td[not(contains(@class, "parameter-action-buttons-cell"))]'
    _DEFINITION_ERRORS_TABLE_ROW_XPATH = '//definition-errors//tbody/tr[contains(@ng-repeat, "definitionError")]'
    _DEFINITION_ERRORS_VALUE_XPATH = '//td/div'
    _TABLE_COLUMNS = 4

    def __init__(self):
        super(DefinitionErrorsPageViewPanel, self).__init__()
        self.common_actions = {
            'load_commissioning_file_and_check_load_status':
                ConfigurationCommonAction().load_commissioning_file_and_check_load_status,
            'validate_plan': ConfigurationCommonAction().validate_plan,
            'activate_plan': ConfigurationCommonAction().activate_plan,
            'save_bts_configuration': ConfigurationCommonAction().save_bts_configuration,
        }
        self.__dict__.update(self.common_actions)

    def get_definition_status(self):
        """
        Get definition status
        :return: str, definition status
        """
        return self.get_text_by_xpath(self._VALIDATE_PLAN_RESULT_XPATH)

    def _get_headers_and_all_definition_errors(self):
        headers = [item.text.strip() for item in
                   self.driver.find_elements_by_xpath(self._DEFINITION_ERRORS_TABLE_HEAD_XPATH)]

        all_error_info = []
        for index, elem in enumerate(self.driver.find_elements_by_xpath(self._ALL_ERROR_INFO_XPATH)):
            if index == self._TABLE_COLUMNS - 1:
                all_error_info.append(elem.find_element_by_tag_name('input').get_attribute('value'))
            all_error_info.append(elem.text.strip())
        return headers, all_error_info

    def get_definition_errors(self, timeout=60):
        definition_errors = []
        try:
            self.wait_for_enable((By.XPATH, self._DEFINITION_ERRORS_TABLE_XPATH), timeout)
            headers, all_error_info = self._get_headers_and_all_definition_errors()

            for i in range(len(all_error_info) // self._TABLE_COLUMNS):
                values = all_error_info[i * self._TABLE_COLUMNS:(i + 1) * self._TABLE_COLUMNS: 1]
                definition_errors.append(dict(zip(headers, values)))
        except TimeoutException:
            pass
        finally:
            return definition_errors


