class BtsCertificatesPage(object):
    """
    As a class will be called by Configuration,
    all operations on BTS Certificates will be implemented under this class.
    """
    MENU_ROUTE_LIST = ['Configuration', 'Certificate Management', 'BTS Certificates']
    _TA_CERTIFICATES_XPATH = "//wf-pane[@label='BTS Certificates']//span[text()='TA']"
    _CA_CERTIFICATES_XPATH = "//wf-pane[@label='BTS Certificates']//span[text()='CA']"
    _BTS_CERTIFICATES_XPATH = "//wf-pane[@label='BTS Certificates']//span[text()='BTS']"

    def __init__(self):
        self._view_panel = BtsCertificatesPageViewPanel()
        self._detail_panel = BtsCertificatesPageDetailPanel()

    def _get_detail_panel_info(self, xpath, index=0):
        self._detail_panel.expand_details_panel()
        self._view_panel.show_detail_panel(xpath, index)
        return self._detail_panel.get_certificate_details_info()

    def delete_certificate(self, serial_numbers, timeout=60):
        self._view_panel.delete_certificate(serial_numbers, timeout)

    def get_certificates(self, timeout, cert_type=None, index=0):
        cert_xpath_dict = {'TA': self._TA_CERTIFICATES_XPATH,
                           'CA': self._CA_CERTIFICATES_XPATH,
                           'BTS': self._BTS_CERTIFICATES_XPATH}
        if cert_type:
            cert_xpath_dict = {
                key: cert_xpath_dict[key] for key in cert_xpath_dict.keys()
                if key is cert_type}
        cert_dict = {}
        try:
            self._view_panel.expand_certificates_list(timeout)
        except TimeoutException:
            logging.warning("No certificate is found.")
            return cert_dict
        for cert_type, cert_xpath in cert_xpath_dict.items():
            if self._view_panel.check_if_exists((By.XPATH, cert_xpath)):
                cert_dict[cert_type] = self._get_detail_panel_info(
                    cert_xpath, index)
        return cert_dict

    def get_certificates_number(self, cert_type=None):
        cert_xpath_dict = {'TA': self._TA_CERTIFICATES_XPATH,
                           'CA': self._CA_CERTIFICATES_XPATH,
                           'BTS': self._BTS_CERTIFICATES_XPATH}
        if not cert_type:
            raise Exception('Certificate type does not specified')
        return len(self._view_panel.driver.find_elements_by_xpath(cert_xpath_dict[cert_type]))

    def add_certificate(self, file_path, timeout=60):
        _LOAD_CERTIFICATE_FILE_BUTTON_SCRIPT = ".install-cert-browse-button " \
                                               "ui-file-input input[" \
                                               "accept='.pem,.der,.crt,.cer']"
        _LOAD_CERTIFICATE_FILE_BUTTON_XPATH = '//label[contains(text(), ' \
                                              '"Additional CA certificates")]/..//input[@accept=".pem,.der,.crt,.cer"]'
        _INSTALL_BUTTON_XPATH = "//bts-certificates//button[contains(text(), 'Install')]"
        self._detail_panel.load_file_from_hidden_button(
            _LOAD_CERTIFICATE_FILE_BUTTON_SCRIPT,
            _LOAD_CERTIFICATE_FILE_BUTTON_XPATH,
            file_path, timeout)
        self._view_panel.wait_for_text_not_present_in_element((
            By.XPATH, _INSTALL_BUTTON_XPATH), 'disabled', timeout=10)
        self._detail_panel.click_enabled_element((
            By.XPATH, _INSTALL_BUTTON_XPATH))

    def install_bts_certificates_from_local(self, bts_file_path, password, additional_ca_file_path, timeout):
        """
        Keyword for install certificates from local in BTS Certificates page
        :param bts_file_path: file, bts certificates file
        :param password: str, password for install certificates
        :param additional_ca_file_path: file, additional certificates file
        :param timeout: int, time to wait file load, default is 60 second
        :return: str, result of install certificates
        """
        return self._view_panel.install_bts_certificates_from_local(bts_file_path, password, additional_ca_file_path,
                                                                    timeout)


